DO $$
BEGIN
  IF (SELECT count(*) FROM public.courses WHERE id = 'prompt_engineering' AND description = 'Design, test, and improve prompts and multi-step LLM workflows for useful, verifiable outcomes.') <> 1 THEN RAISE EXCEPTION 'Modern course snapshot changed: prompt_engineering'; END IF;
  IF (SELECT count(*) FROM public.courses WHERE id = 'generative_ai_llm' AND description = 'Build LLM applications using model APIs, structured outputs, embeddings, conversation state, and practical reliability controls.') <> 1 THEN RAISE EXCEPTION 'Modern course snapshot changed: generative_ai_llm'; END IF;
  IF (SELECT count(*) FROM public.courses WHERE id = 'mcp_tool_connected_ai' AND description = 'Connect AI applications to external capabilities using MCP concepts, server-provided tools/resources, and explicit permissions.') <> 1 THEN RAISE EXCEPTION 'Modern course snapshot changed: mcp_tool_connected_ai'; END IF;
  IF (SELECT count(*) FROM public.lessons WHERE id = '80f74c3a-492f-4efe-aaba-4ae628c9721a' AND module_id = 'eb427a53-1c31-4c0b-91fd-bfdfdfb806af' AND title = 'MCP and Adjacent Integration Patterns' AND lesson_order = 2 AND content = '<section class="lesson-section"><h3>Story</h3><p>A desktop assistant can explain a spreadsheet formula but cannot inspect the user&#39;s authorized workbook until connected to a capability.</p></section>
<section class="lesson-section"><h3>Discovery</h3><p>Identify what the model can infer and what requires an external, permissioned tool or resource.</p></section>
<section class="lesson-section"><h3>Learning Objective</h3><p>Distinguish MCP from direct API calls and model function-calling schemas.</p></section>
<section class="lesson-section"><h3>Concept</h3><p>MCP is a protocol for connecting AI applications with servers that expose capabilities such as tools, resources, and prompts. A direct API is an application-specific interface; function calling is a model interaction pattern and may be used inside an MCP-enabled host.</p></section>
<section class="lesson-section"><h3>Example</h3><p>A host can discover an MCP server&#39;s tools, while a separate model call decides whether to propose one of those tools.</p></section>
<section class="lesson-section"><h3>Challenge</h3><p>Classify four integration diagrams as direct API, function calling, MCP, or combinations and explain the protocol boundary.</p></section>
<section class="lesson-section"><h3>Takeaway</h3><p>MCP standardizes a connection protocol; it is not itself a model or a generic synonym for APIs.</p></section>') <> 1 THEN RAISE EXCEPTION 'MCP lesson snapshot changed'; END IF;
END $$;
